ALTER TABLE `matters` ADD `professional_fields` text DEFAULT '{}' NOT NULL CONSTRAINT `project_professional_fields_valid` CHECK(CASE WHEN length(CAST(`professional_fields` AS blob)) <= 28000 AND json_valid(`professional_fields`) THEN json_type(`professional_fields`) = 'object' AND json_remove(`professional_fields`, '$.civil_litigation', '$.criminal_litigation', '$.commercial_arbitration', '$.non_litigation', '$.contract_review') = '{}' AND COALESCE(json_type(`professional_fields`, '$.civil_litigation'), 'object') = 'object' AND COALESCE(json_type(`professional_fields`, '$.criminal_litigation'), 'object') = 'object' AND COALESCE(json_type(`professional_fields`, '$.commercial_arbitration'), 'object') = 'object' AND COALESCE(json_type(`professional_fields`, '$.non_litigation'), 'object') = 'object' AND COALESCE(json_type(`professional_fields`, '$.contract_review'), 'object') = 'object' ELSE 0 END);
